import type { FileSystemService } from '@google/gemini-cli-core';
import { isWithinRoot } from '@google/gemini-cli-core';
import type * as acp from '@agentclientprotocol/sdk';
import * as os from 'node:os';
import * as path from 'node:path';

/**
 * ACP client-based implementation of FileSystemService
 */
export class AcpFileSystemService implements FileSystemService {
  constructor(
    private readonly connection: acp.AgentSideConnection,
    private readonly sessionId: string,
    private readonly capabilities: acp.FileSystemCapabilities,
    private readonly fallback: FileSystemService,
    private readonly root: string,
  ) {}

  /**
   * Determines whether an operation for the given path should be forwarded to
   * the remote connection. Operations are only forwarded when the path is
   * within the configured root directory and is not inside the user's global
   * tool configuration folder.
   */
  private shouldUseRemote(filePath: string): boolean {
    const geminiDir = path.join(os.homedir(), '.gemini');
    return isWithinRoot(filePath, this.root) && !isWithinRoot(filePath, geminiDir);
  }

  async readTextFile(filePath: string): Promise<string> {
    if (!this.capabilities.readTextFile || !this.shouldUseRemote(filePath)) {
      return this.fallback.readTextFile(filePath);
    }

    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      const response = await this.connection.readTextFile({
        path: filePath,
        sessionId: this.sessionId,
      });

      // eslint-disable-next-line @typescript-eslint/no-unsafe-return
      return response.content;
    } catch (error) {
      throw this.translateError(error);
    }
  }

  async writeTextFile(filePath: string, content: string): Promise<void> {
    if (!this.capabilities.writeTextFile || !this.shouldUseRemote(filePath)) {
      return this.fallback.writeTextFile(filePath, content);
    }

    try {
      await this.connection.writeTextFile({
        path: filePath,
        content,
        sessionId: this.sessionId,
      });
    } catch (error) {
      throw this.translateError(error);
    }
  }

  /**
   * Translates specific remote errors into standard filesystem errors.
   */
  private translateError(error: unknown): unknown {
    const message = error instanceof Error ? error.message : String(error);
    if (message.includes('Resource not found')) {
      const enoent = new Error(message) as Error & { code: string };
      enoent.code = 'ENOENT';
      return enoent;
    }
    return error;
  }
}
